<?php require __DIR__.'/_layout_start.php'; ?><h1><?= (int)$resource['id']?'Modifica':'Nuova' ?> risorsa Assistenza</h1><?php foreach($errors as $e): ?><div class="error"><?= htmlspecialchars($e,ENT_QUOTES,'UTF-8') ?></div><?php endforeach; ?><form class="panel formgrid" method="post" action="/admin/assistance/save"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrf,ENT_QUOTES,'UTF-8') ?>"><input type="hidden" name="id" value="<?= (int)$resource['id'] ?>"><label>Sezione<select name="section"><option value="warranty" <?= $resource['section']==='warranty'?'selected':'' ?>>Garanzia di prodotto</option><option value="error_code" <?= $resource['section']==='error_code'?'selected':'' ?>>Codici di errore</option></select></label><label>Etichetta<input name="label" maxlength="220" required value="<?= htmlspecialchars((string)$resource['label'],ENT_QUOTES,'UTF-8') ?>"></label><label class="full">Documento<select name="document_id"><option value="">Nessun documento</option><?php foreach($documents as $d): ?><option value="<?= (int)$d['id'] ?>" <?= (int)$resource['document_id']===(int)$d['id']?'selected':'' ?>><?= htmlspecialchars($d['title'],ENT_QUOTES,'UTF-8') ?></option><?php endforeach; ?></select><small>Preferibile per i PDF migrati nel nuovo archivio.</small></label><label class="full">URL esterno<input name="external_url" maxlength="500" value="<?= htmlspecialchars((string)($resource['external_url']??''),ENT_QUOTES,'UTF-8') ?>"><small>Usalo solo quando la risorsa resta esterna al nuovo sito.</small></label><label>Ordine<input type="number" name="sort_order" value="<?= (int)$resource['sort_order'] ?>"></label><label class="check"><input type="checkbox" name="published" value="1" <?= $resource['published']?'checked':'' ?>> Pubblicato</label><div class="full"><button class="btn" type="submit">Salva</button> <a href="/admin/assistance">Torna all'elenco</a></div></form><?php require __DIR__.'/_layout_end.php'; ?>
